import json
Wl = []
def write(a, y):
    Wl.append([a, y, len(Wl), 0])
    for e in Wl:
        e[3] = sum(1 for f in Wl if f[2] > e[2] and f[0] == e[0])
for a, y in [(4, 1), (9, 2), (4, 3), (4, 5), (9, 8)]:
    write(a, y)
print(json.dumps({"counts": [e[3] for e in Wl], "answer_4": [e[1] for e in Wl if e[0] == 4 and e[3] == 0][0]}))
